import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    category_mapping = {"Office Suplies": "Office Supplies", "Furnture": "Furniture"}
    df["Category"] = df["Category"].replace(category_mapping)
    df = df[df["Quantity"] >= 1]
    return df

def answer(df):
    averages = df.groupby("Category")["Price"].mean()
    return {cat: float(avg) for cat, avg in averages.items()}
